// 이 파일은 **손으로 쓴 것이다.** 생성하지 않는다 — tools/gen/groups.go 의 handWritten 참고.
//
// 생성물 헤더("Code generated by tools/gen. DO NOT EDIT.")를 붙이지 마라. 붙이는 순간
// cleanGenerated 가 다음 생성 때 이 파일을 지우고, 골든 테스트는 "생성 대상이 아닌데
// 헤더가 붙었다"(orphan)로 터진다. 헤더가 없으면 둘 다 이 파일을 건드리지 않는다.
//
// ka10173 만 손으로 쓰는 이유: 337개 중 유일하게 **응답이 두 벌**이다. 조회 결과가 한 번
// 오고, 그 뒤로 REAL 푸시가 계속 온다. 스펙에서도 이것만 is_section 으로 본문이 갈라져
// 생성기의 BuildTree 가 접다가 에러를 낸다. 하나를 위해 생성기에 분기를 넣는 것보다,
// 하나를 손으로 쓰고 생성기를 단순하게 두는 편이 낫다.
//
// 그 대신 **모양은 생성물과 같게** 맞춘다 — ka10171·ka10172·ka10174 를 쓰다가 여기로 온
// 사용자가 낯설지 않아야 한다. 요청 구조체에 trnm 이 없고(전송 직전에 끼운다), 응답
// 구조체에 return_code·return_msg 가 없다(전송 계층이 *kiwoom.WSAPIError 로 바꾼다).

package condition

import (
	"context"
	"encoding/json"

	"github.com/kenshin579/kiwoom-go/internal/wstransport"
	"github.com/kenshin579/kiwoom-go/stream"
)

// RequestDomesticRealtimeConditionSearchRequest 는 조건검색 요청 실시간(ka10173) 요청이다.
//
// trnm 은 여기 없다. 값이 CNSRREQ 하나로 정해져 있어 호출자가 고를 것이 없고, 비워 두면
// 서버 응답이 짝을 찾지 못해 ctx 만료까지 조용히 매달린다 — 전송 직전에 아래 메서드가 넣는다.
type RequestDomesticRealtimeConditionSearchRequest struct {
	// 조건검색식 일련번호 (필수, 3자)
	Seq string `json:"seq"`
	// 조회타입 (필수, 1: 조건검색+실시간조건검색)
	SearchType string `json:"search_type"`
	// 거래소구분 (필수, 1자, K:KRX)
	StexTp string `json:"stex_tp"`
}

// RequestDomesticRealtimeConditionSearchResponse 는 조건검색 요청 실시간(ka10173) 의
// **조회 응답**이다. 푸시 이전에 한 번 온다.
//
// return_code·return_msg 는 여기 없다. 전송 계층이 return_code != 0 을 *kiwoom.WSAPIError
// 로 바꿔 주므로, 이 구조체를 받았다는 것 자체가 이미 정상이라는 뜻이다(정상이면 스펙상
// return_msg 도 비어 있다). 게다가 스펙은 결과코드를 String 이라 적었지만 서버는 int 로
// 보내 — 남겨 두면 응답 파싱이 통째로 실패한다.
type RequestDomesticRealtimeConditionSearchResponse struct {
	// 서비스명 (CNSRREQ)
	Trnm string `json:"trnm"`
	// 조건검색식 일련번호
	Seq string `json:"seq"`
	// 검색결과데이터
	Data []RequestDomesticRealtimeConditionSearchDataItem `json:"data"`
}

// RequestDomesticRealtimeConditionSearchDataItem 는 Data 의 원소다.
type RequestDomesticRealtimeConditionSearchDataItem struct {
	// 종목코드 (접두어 1자리 + 종목코드 6자리, 접두어(A: 주식 / J: ELW / Q: ETN))
	Jmcode string `json:"jmcode"`
}

// DomesticRealtimeConditionMatch 는 조건검색 편입·이탈 푸시 한 건이다.
//
// 필드 이름은 tools/gen/fids.go 의 표에서 왔다 — 생성된 실시간 구조체와 같은 출처이고,
// 같은 FID 는 어디서나 같은 낱말이다(841 SequenceNumber · 9001 StockOrSectorCode ·
// 843 InsertDeleteType · 20 TradeTime · 907 TradeSide).
type DomesticRealtimeConditionMatch struct {
	// 일련번호 (요청한 조건검색식의 seq 가 그대로 온다)
	SequenceNumber string `json:"841"`
	// 종목코드
	StockOrSectorCode string `json:"9001"`
	// 삽입삭제 구분 (I: 삽입, D: 삭제)
	InsertDeleteType string `json:"843"`
	// 체결시간
	TradeTime string `json:"20"`
	// 매도/수 구분
	TradeSide string `json:"907"`
}

// RequestDomesticRealtimeConditionSearch 는 조건검색 요청 실시간(ka10173) 이다.
// WebSocket 위의 요청/응답이고, 그 뒤로 편입·이탈 푸시가 이어진다.
//
// 조회 응답을 돌려주고, 그 뒤의 푸시를 채널로 흘린다. 푸시는 종목별 등록(REG)이 아니라
// **이 요청 자체가 등록**이라, 채널은 조건검색식 일련번호(req.Seq)로 갈린다.
//
// ctx 를 취소하면 채널이 닫힌다. 다만 그것은 받기를 그만두는 것일 뿐 **서버에 해제를
// 보내지 않는다** — 실시간 해제는 StopDomesticRealtimeConditionSearch(ka10174)로 따로
// 보내야 한다. 그러지 않으면 서버는 계속 밀어 보낸다.
//
// 채널이 가득 차면 이벤트를 버리고 *kiwoom.SlowConsumerError 를 흘린다. 끊겼다 붙으면
// *kiwoom.GapError 가 온다 — 실시간 구독과 같은 처리다. 다만 뜻이 하나 더 있다:
// **조건검색 등록은 재연결이 되살리지 못한다.** REG 로 되살릴 수 있는 등록이 아니기
// 때문이다. 그래서 이 채널의 GapError 는 "그 사이를 놓쳤다" 에 더해 "지금은 아무것도
// 오지 않는다" 는 뜻이다 — 받으면 이 메서드를 다시 불러 등록을 새로 세워야 한다.
//
// 메뉴: 국내주식 > 조건검색 > 조건검색 요청 실시간(ka10173)
// URL:  /api/dostk/websocket  (trnm: CNSRREQ, 이후 REAL 푸시)
func (c *Client) RequestDomesticRealtimeConditionSearch(
	ctx context.Context, req RequestDomesticRealtimeConditionSearchRequest,
) (*RequestDomesticRealtimeConditionSearchResponse, <-chan stream.Event[DomesticRealtimeConditionMatch], error) {
	// 라우팅을 **요청보다 먼저** 붙인다.
	//
	// 응답을 받은 뒤에 붙이면 그 사이에 온 첫 푸시가 갈 곳이 없어 버려진다. 조건검색은
	// 요청하는 순간 서버가 밀기 시작하므로 그 틈이 실제로 있다. 열쇠는 응답을 기다릴
	// 것도 없이 이미 손에 있다 — 호출자가 준 seq 가 곧 푸시의 841 이다.
	subCtx, cancel := context.WithCancel(ctx)
	// 실패해서 돌아가는 길에는 라우팅을 뗀다. 남겨 두면 오지 않을 푸시를 기다리는 채널이
	// ctx 끝까지 열린 채 남는다. 채널을 넘겨준 뒤에는 ctx 가 그 일을 맡는다.
	handedOff := false
	defer func() {
		if !handedOff {
			cancel()
		}
	}()

	src, err := c.ws.SubscribeCondition(subCtx, req.Seq, defaultBuffer)
	if err != nil {
		return nil, nil, err
	}

	body := struct {
		Trnm string `json:"trnm"`
		RequestDomesticRealtimeConditionSearchRequest
	}{Trnm: "CNSRREQ", RequestDomesticRealtimeConditionSearchRequest: req}

	var out RequestDomesticRealtimeConditionSearchResponse
	if err := c.ws.Request(ctx, "CNSRREQ", body, &out); err != nil {
		return nil, nil, err
	}

	ch := make(chan stream.Event[DomesticRealtimeConditionMatch], defaultBuffer)
	go func() {
		defer close(ch)
		for d := range src {
			ch <- decodeDomesticRealtimeConditionMatch(d)
		}
	}()
	handedOff = true
	return &out, ch, nil
}

func decodeDomesticRealtimeConditionMatch(d wstransport.Delivery) stream.Event[DomesticRealtimeConditionMatch] {
	// 봉투는 봉투째 옮긴다(생성된 실시간 decode 와 같은 규칙). StexTp 는 국내 푸시에
	// 없어 늘 빈 문자열이지만, 한 곳에서만 옮기면 다른 곳에서 조용히 사라진다.
	ev := stream.Event[DomesticRealtimeConditionMatch]{
		Symbol: d.Item, Name: d.Name, StexTp: d.StexTp, Time: d.Time, Err: d.Err,
	}
	if d.Err != nil {
		return ev
	}
	// 두 번 푼다. 구조체는 표에 있는 FID 만 받고, Raw 는 전부 받는다 —
	// 키움이 FID 를 추가했을 때 encoding/json 이 조용히 버리지 않게 한다.
	if err := json.Unmarshal(d.Values, &ev.Value); err != nil {
		ev.Err = err
		return ev
	}
	if err := json.Unmarshal(d.Values, &ev.Raw); err != nil {
		ev.Err = err
	}
	return ev
}
